import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { unzip } from "./src/array/unzip.js";
{
{
{
const zipped = [
            ['a', 1, true, 32, 100],
            ['b', 2, false],
        ];
        const result = unzip(zipped);
        expect(result).toEqual([
            ['a', 'b'],
            [1, 2],
            [true, false],
            [32, undefined],
            [100, undefined],
        ]);
        const zipped2 = [['a', 1, true], ['b', 2, false, 32, 58], [1]];
        const result2 = unzip(zipped2);
        expect(result2).toEqual([
            ['a', 'b', 1],
            [1, 2, undefined],
            [true, false, undefined],
            [undefined, 32, undefined],
            [undefined, 58, undefined],
        ]);
}
}
}
